package io.github.smyrna_pergamum.exercisetracker.domain

import io.github.smyrna_pergamum.exercisetracker.R

enum class Measure { REPS, TIME }

enum class Group(val label: Int) {
    UPPER(R.string.group_upper),
    LEGS(R.string.group_legs),
    CORE(R.string.group_core),
    CARDIO(R.string.group_cardio),
    YOGA(R.string.group_yoga),
    PILATES(R.string.group_pilates),
}

/**
 * A built-in exercise. Text lives in string resources, pictures in drawables generated by
 * tools/draw_exercises.py, so every exercise always has both and works offline.
 */
data class Exercise(
    val id: String,
    val group: Group,
    val measure: Measure,
    /** Uses dumbbells, so a load field is shown. */
    val weighted: Boolean,
    val title: Int,
    val steps: Int,
    val imageA: Int,
    val imageB: Int,
)

