    fun isYoga(id: String) = get(id)?.group == Group.YOGA
    fun isPilates(id: String) = get(id)?.group == Group.PILATES

    private val byId = all.associateBy { it.id }

    fun get(id: String): Exercise? = byId[id]

    private fun e(id: String, g: Group, title: Int, steps: Int, a: Int, b: Int, m: Measure = Measure.REPS, weighted: Boolean = false) =
        Exercise(id, g, m, weighted, title, steps, a, b)
